void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = 4.0*fragCoord/iResolution.xx;

    // load image
    vec3 img = texture(iChannel0,uv).xyz;
    vec3 img2 = img;
    vec3 img1 = img * mat3(0.4124564, 0.3575761, 0.1804375, 0.2126729, 0.7151522, 0.0721750, 0.0193339, 0.1191920, 0.9503041);
    img1 *= mat3(0.4002, 0.7076, -0.07868, -0.22981, 1.18340, 0.04641, 0.0, 0.0, 1.0);
    img1 = vec3((img.r+img.g+img.b)/3.0,(img.r+img.g+img.b)/3.0,(img.r+img.g+img.b)/3.0);
    vec3 img3 = vec3(dot(img, vec3(0.2126, 0.7152, 0.0722)),dot(img, vec3(0.2126, 0.7152, 0.0722)),dot(img, vec3(0.2126, 0.7152, 0.0722)));


    if(uv.x<1.0) {
        img = img1;
    }
    if(uv.x>1.0) {
        img = img2;
    }
    if(uv.x>2.0) {
        img = img3;
    }
    if(uv.x>3.0) {
        img = abs(img1-img3);
    }

    // Output to screen
    fragColor = vec4(img, 1.0);
}
